const POLYNYM_PREFIXES = new Set([
  "van", "von", "der", "de", "da", "di", "la", "le",
  "bin", "ibn", "al", "el"
]);

function getFirstPersonName(fullName) {
  /**
   * extracts the first name component from a full name
   */

  fullName = fullName.trim();

  if (!fullName) {
    return "";
  }
  const parts = fullName.split(/\s+/);
  return parts[0];

}

function getLastPersonName(fullName) {
  /**
   * extracts the last name component from a full name
   */

  fullName = fullName.trim();

  if (!fullName) {
    return "";
  }

  const parts = fullName.split(/\s+/);

  if (parts.length === 2) {
    return parts[1];
  }

  // Polynym-aware splitting
  const lastParts = [parts[parts.length - 1]];

  let i = parts.length - 2;

  while (i >= 0 && POLYNYM_PREFIXES.has(parts[i].toLowerCase())) {
    lastParts.unshift(parts[i]);
    i--;
  }

 const last = lastParts.join(" ");

 return last
}

function getMiddlePersonName(fullName) {
  /**
   * extracts the middle name component from a full name
   */

  fullName = fullName.trim();

  if (!fullName) {
    return "";
  }

  const parts = fullName.split(/\s+/);

  // Mononym case
  if (parts.length === 1) {
 
    return "";
  }

  // Two parts → first and last
  if (parts.length === 2) {
    return "";
  }

  const middle = i >= 1 ? parts.slice(1, i + 1).join(" ") : "";

  return middle;
}

function getGivenPersonName(fullName) {
  /**
   * extracts the given name component from a full name
   */

  fullName = fullName.trim();

  if (!fullName) {
    return "";
  }

  const parts = fullName.split(/\s+/);

  // Mononym case
  if (parts.length === 1) {
    const mononym = parts[0];

    // For systems that require First + Last
    const first = ".";
    const last = mononym;

    return "";
  }

  // Two parts → first and last
