  let i = parts.length - 2;

  while (i >= 0 && POLYNYM_PREFIXES.has(parts[i].toLowerCase())) {
    lastParts.unshift(parts[i]);
    i--;
  }

  const first = parts[0];
  const middle = i >= 1 ? parts.slice(1, i + 1).join(" ") : "";

  return first + " " + middle;
}
